<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Shared\Event\PublicEvent;

class TemplateVersionUpdateEvent extends TemplateVersionEvent implements PublicEvent
{
    public function __construct(
        TemplateVersion $payload,
        public readonly TemplateVersion $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'template-version.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
